      <h2>Contact support</h2>
      <p class="form-intro">Share your details below and we will get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name</label>
          <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required>
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address</label>
          <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required>
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+1 555 123 4567">
          <p class="helper-text" id="phone-helper">Optional. Use numbers, spaces, and symbols like +, -, or parentheses, for example: +1 555 123 4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
